    async def update_claim(
        self,
        id: str,
        *,
        if_match: typing.Optional[str] = None,
        additional_charges: typing.Optional[typing.Sequence[ClaimChargeWriteRequest]] = OMIT,
        delay_date: typing.Optional[dt.date] = OMIT,
        dispute_reason: typing.Optional[str] = OMIT,
        document_date: typing.Optional[dt.date] = OMIT,
        document_reference: typing.Optional[str] = OMIT,
        due_date: typing.Optional[dt.date] = OMIT,
        is_disputed: typing.Optional[bool] = OMIT,
        items: typing.Optional[typing.Sequence[ClaimItemWriteRequest]] = OMIT,
        legal_basis: typing.Optional[ClaimLegalBasisWriteRequest] = OMIT,
        principal_amount: typing.Optional[ClaimPrincipalAmountWriteRequest] = OMIT,
        reminders: typing.Optional[typing.Sequence[ClaimReminderWriteRequest]] = OMIT,
        subject_matter: typing.Optional[str] = OMIT,
        your_reference: typing.Optional[str] = OMIT,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> Claim:
        """
        Claims addressed by their stable UUID and current relationships.

        Read claims throughout their lifecycle using URLs that remain valid after
        internal order moves. Standalone creation requires a draft `order_id`;
        the relationship is read-only thereafter. Create, PATCH, and DELETE require
        a draft order and otherwise return `409 claim_not_editable`. An expired
        draft instead returns `409 order_expired`. Tenant-scoped by the
        authenticated company.

        Parameters
        ----------
        id : str
            UUID of the claim in this request.

        if_match : typing.Optional[str]
            Apply the change only while the current `ETag` matches one of the supplied validators (or `*`); otherwise the request fails with `412 precondition_failed` and nothing is written.

        additional_charges : typing.Optional[typing.Sequence[ClaimChargeWriteRequest]]
            Itemized incidental charges for a receivable claim, such as reminder or bank fees. This array replaces all existing charges; [] clears them and omission preserves them. Maximum 50 entries per claim.

        delay_date : typing.Optional[dt.date]
            Payment-default date for a receivable claim. For H17/H19 rent, an explicit date overrides the derived day after due_date and null restores derivation. For other receivables, null clears it; changing document_date, due_date, or reminders without supplying delay_date recalculates it. An explicit date must follow the applicable due or reminder date.

        dispute_reason : typing.Optional[str]
            Debtor's stated reason for disputing the claim. The resulting disputed claim must have a non-blank reason; an existing reason satisfies this requirement when omitted from PATCH. Setting is_disputed to false clears the existing reason unless you supply this field, which must then be empty or null.

        document_date : typing.Optional[dt.date]
            Date of the invoice, contract, or other claim document. For H17/H19 rent, supply the first day of the rental month; only one rental claim per calendar month is allowed. Only valid for receivable claims. Required and cannot be in the future at finalization.

        document_reference : typing.Optional[str]
            Invoice, contract, or other source-document number.

        due_date : typing.Optional[dt.date]
            Date on which a receivable claim became due. For H17/H19 rent, an explicit date overrides the agreement rule, null restores derivation, and omission preserves the current date or its existing derivation. For other receivables it cannot precede document_date.

        is_disputed : typing.Optional[bool]
            Whether the debtor disputes the claim. Setting false also clears the existing dispute_reason unless you supply that field explicitly.

        items : typing.Optional[typing.Sequence[ClaimItemWriteRequest]]
            Invoice or contract lines for a receivable claim. This array replaces all existing lines; [] clears them and omission preserves them. Supply principal_amount separately when the principal changes. Maximum 100 entries per claim.

        legal_basis : typing.Optional[ClaimLegalBasisWriteRequest]
            Contract or obligation establishing a receivable claim. Supplied properties update the existing legal basis; omitted properties stay unchanged. Not valid on titled claims or on receivable enforcement costs in titled orders, which always use K014.

        principal_amount : typing.Optional[ClaimPrincipalAmountWriteRequest]
            Replacement principal amount including VAT, before charges and payments. Only valid for receivable claims; titled claims use their enforceable-title amount. Changing items does not update this amount. The principal must be positive before finalization.

        reminders : typing.Optional[typing.Sequence[ClaimReminderWriteRequest]]
            Payment reminders for a receivable claim, in chronological order starting no earlier than its due date (or document date when due_date is absent). This array replaces all reminders; [] clears them and omission preserves them. Retain existing entries with their id. Maximum 50 entries per claim.

        subject_matter : typing.Optional[str]
            Goods, services, or other obligation underlying the claim. Before finalization, a receivable claim must have non-blank subject_matter or at least one claim document. Maximum 2000 characters.

        your_reference : typing.Optional[str]
            Your reference for this claim.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        Claim


        Examples
        --------
        import asyncio
        import datetime

        from paywise import AsyncPaywise

        client = AsyncPaywise(
            on_behalf_of_company="YOUR_ON_BEHALF_OF_COMPANY",
            token="YOUR_TOKEN",
        )


        async def main() -> None:
            await client.case_management.claims.update_claim(
                id="id",
                due_date=datetime.date.fromisoformat(
                    "2026-06-26",
                ),
                subject_matter="Website accessibility consulting in June 2026 (rev. 2)",
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.update_claim(
            id,
            if_match=if_match,
            additional_charges=additional_charges,
            delay_date=delay_date,
            dispute_reason=dispute_reason,
            document_date=document_date,
            document_reference=document_reference,
            due_date=due_date,
            is_disputed=is_disputed,
            items=items,
            legal_basis=legal_basis,
            principal_amount=principal_amount,
            reminders=reminders,
            subject_matter=subject_matter,
            your_reference=your_reference,
            request_options=request_options,
        )
        return _response.data
